// Generated from src/registry/sources/control-ui/recipes/choice.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const choiceKnobs = [
  "--cui-choice-size",
  "--cui-choice-indicator-size",
  "--cui-choice-radius",
  "--cui-choice-border-color",
  "--cui-choice-border-width",
  "--cui-choice-background",
  "--cui-choice-checked-background",
  "--cui-choice-checked-border-color",
  "--cui-choice-shadow",
] as const;
export type ChoiceKnobStyle = Partial<Record<(typeof choiceKnobs)[number], string>>;

@layer components {
  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --cui-choice-size: calc(var(--spacing) * 4);
    --cui-choice-indicator-size: calc(var(--cui-choice-size) * 0.75);
    inline-size: var(--cui-choice-size);
    block-size: var(--cui-choice-size);
    --cui-choice-radius: var(--radius-sm);
    --cui-choice-shadow: var(--shadow-sm);
    --cui-choice-border-color: var(--control-boundary);
    --cui-choice-border-width: var(--control-rim-width);
    --cui-choice-checked-background: var(--primary);
    --cui-choice-checked-border-color: var(--primary);
    --cui-choice-background: var(--control-fill);
    --_choice-background: var(--cui-choice-background);
    --_choice-border-color: var(--cui-choice-border-color);
    --_choice-ring: 0 0 transparent;
    border-radius: var(--cui-choice-radius);
    background: var(--_choice-background);
    box-shadow:
      inset 0 0 0 var(--cui-choice-border-width) var(--_choice-border-color),
      var(--cui-choice-shadow),
      var(--_choice-ring);
    color: currentColor;
    cursor: pointer;
    transition-property: background-color, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --cui-choice-radius: 9999px;
    --cui-choice-indicator-size: calc(var(--cui-choice-size) * 0.375);
  }

  @media (hover: hover) {
    :where(
        [data-control-family="choice"]:is(
          [data-choice-kind="checkbox"][data-slot="root"],
          [data-choice-kind="radio-group"][data-slot="item"]
        ):hover:not([data-disabled], [data-readonly])
      ) {
      --_choice-border-color: color-mix(in oklch, var(--cui-choice-border-color), var(--foreground) 35%);
    }
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:is([data-checked], [data-indeterminate])),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:is([data-checked], [data-indeterminate])) {
    --_choice-background: var(--cui-choice-checked-background);
    --_choice-border-color: var(--cui-choice-checked-border-color);
    color: var(--primary-foreground);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"][data-disabled]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-disabled]) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:is([data-invalid], [aria-invalid="true"])),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:is([data-invalid], [aria-invalid="true"])) {
    --_choice-border-color: var(--destructive);
    --_choice-ring: 0 0 0 1px var(--destructive);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"] [data-slot="indicator"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"] [data-slot="indicator"]) {
    color: currentColor;
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"] [data-slot="indicator"]) {
    border-radius: 9999px;
    background: var(--primary-foreground);
  }

  :where([data-control-family="checkbox-group"][data-slot="root"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="root"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="checkbox-group"][data-slot="root"][data-orientation="horizontal"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="root"][data-orientation="horizontal"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="checkbox-group"][data-slot="root"][data-track="hover"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="root"][data-track="hover"]) {
    gap: 0;
  }

  :where([data-control-family="checkbox-group"][data-slot="item"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="label"]) {
    gap: calc(var(--spacing) * 2.5);
    padding: calc(var(--spacing) * 2);
    border-radius: var(--radius-control);
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    cursor: pointer;
  }

  :where([data-control-family="checkbox-group"][data-slot="item"]:has([data-disabled])),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="label"]:has([data-disabled])) {
    cursor: not-allowed;
  }

  :where([data-control-family="choice"][data-slot="indicator"]:is([data-choice-kind="radio-group"], [data-choice-kind="checkbox"])) {
    inline-size: var(--cui-choice-indicator-size);
    block-size: var(--cui-choice-indicator-size);
  }

  @media (pointer: coarse) {
    :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"])::after,
    :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"])::after {
      content: "";
      position: absolute;
      inset: 50% auto auto 50%;
      translate: -50% -50%;
      inline-size: max(100%, var(--touch-target));
      block-size: max(100%, var(--touch-target));
    }
  }

  @media (forced-colors: active) {
    :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:not(:focus-visible)),
    :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:not(:focus-visible)) {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }

    :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:is([data-checked], [data-indeterminate])),
    :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-checked]) {
      background: Highlight;
      color: HighlightText;
    }

    :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="indicator"]) {
      background: HighlightText;
    }
  }
}

@property --cui-choice-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-choice-indicator-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-choice-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-choice-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-choice-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-checked-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-checked-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-shadow {
  syntax: "*";
  inherits: true;
}

"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import type { ComponentProps, CSSProperties } from "react";
import type { ChoiceKnobStyle } from "@/components/control-ui/knob-contracts/choice-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type CheckboxProps = Omit<ComponentProps<typeof CheckboxPrimitive.Root>, "className" | "style" | "children"> & {
  className?: string;
  style?: CSSProperties & ChoiceKnobStyle;
};

// tick and dash swap on Root's data-indeterminate in pure CSS.
export function Checkbox({ className, ...props }: CheckboxProps) {
  return (
    <CheckboxPrimitive.Root
      data-control-ui="checkbox"
      data-choice-kind="checkbox"
      data-control-family="choice"
      data-slot="root"
      className={cn("group/checkbox relative inline-flex shrink-0 items-center justify-center", className)}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-control-ui="checkbox"
        data-control-family="choice"
        data-choice-kind="checkbox"
        data-slot="indicator"
        className="flex items-center justify-center data-[unchecked]:hidden"
      >
        {/* tick (default) and dash (indeterminate) both mount; Root's data-indeterminate toggles which shows */}
        <svg viewBox="0 0 12 12" className="size-full group-data-[indeterminate]/checkbox:hidden" aria-hidden="true" fill="none">
          <path d="M2.5 6.5 5 9l4.5-5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
        <svg viewBox="0 0 12 12" className="hidden size-full group-data-[indeterminate]/checkbox:block" aria-hidden="true" fill="none">
          <path d="M2.75 6h6.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
        </svg>
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
